<?php require 'auth.php'; require_login(); require 'api/db.php'; $mes=$_GET['mes']??date('Y-m'); $st=$pdo->prepare("SELECT v.*,m.nombre nombre_medico,m.especialidad,m.centro_salud,p.nombre nombre_producto FROM visitas v JOIN medicos m ON m.id_medico=v.id_medico JOIN productos p ON p.id_producto=v.id_producto WHERE strftime('%Y-%m',v.fecha)=? ORDER BY v.fecha,v.hora");$st->execute([$mes]);$visitas=$st->fetchAll();$sf=$pdo->prepare("SELECT vf.*,f.nombre nombre_farmacia,f.direccion,f.encargado FROM visitas_farmacias vf JOIN farmacias f ON f.id_farmacia=vf.id_farmacia WHERE strftime('%Y-%m',vf.fecha)=? ORDER BY vf.fecha");$sf->execute([$mes]);$farmacias=$sf->fetchAll(); ?><!doctype html><html lang="es"><head><meta charset="utf-8"><title>Reporte de visita <?=$mes?></title><style>body{font:12px Arial;color:#172b4d;margin:28px}h1{color:#24527a}h2{background:#24527a;color:white;padding:7px;font-size:14px}table{border-collapse:collapse;width:100%;margin-bottom:18px}th,td{border:1px solid #8da2b5;padding:6px;text-align:left}th{background:#dce8f1}.print{float:right;padding:8px 14px}@media print{.print{display:none}}</style></head><body><button class="print" onclick="print()">Imprimir / Guardar PDF</button><h1>FORMATO DE ENTREGA / REPORTE DE VISITA MÉDICA</h1><p><b>Visitador:</b> <?=htmlspecialchars($u['nombre']??'')?> &nbsp; <b>Fecha del reporte:</b> <?=htmlspecialchars($mes)?></p><h2>1. Resumen de actividad diaria</h2><p>Total de médicos visitados: <b><?=count($visitas)?></b> &nbsp; Total de farmacias visitadas: <b><?=count($farmacias)?></b></p><h2>2. Detalle de visitas a médicos</h2><table><tr><th>Fecha/Hora</th><th>Médico</th><th>Especialidad</th><th>Institución</th><th>Producto</th><th>Muestras/Material</th><th>Compromisos</th></tr><?php foreach($visitas as $v): ?><tr><td><?=$v['fecha']?> <?=$v['hora']?></td><td><?=htmlspecialchars($v['nombre_medico'])?></td><td><?=htmlspecialchars($v['especialidad'])?></td><td><?=htmlspecialchars($v['centro_salud']??'')?></td><td><?=htmlspecialchars($v['nombre_producto'])?></td><td><?=htmlspecialchars($v['muestras_material']??$v['material_entregado']??'')?></td><td><?=htmlspecialchars($v['compromisos']??'')?></td></tr><?php endforeach; ?></table><h2>3. Detalle de visitas a farmacias (Transferencia / Stock)</h2><table><tr><th>Farmacia</th><th>Dirección</th><th>Encargado</th><th>Stock</th><th>Pedido sugerido</th><th>Observaciones</th></tr><?php foreach($farmacias as $f): ?><tr><td><?=htmlspecialchars($f['nombre_farmacia'])?></td><td><?=htmlspecialchars($f['direccion'])?></td><td><?=htmlspecialchars($f['encargado']??'')?></td><td><?=htmlspecialchars($f['stock_productos']??'')?></td><td><?=htmlspecialchars($f['pedido_sugerido']??'')?></td><td><?=htmlspecialchars($f['observaciones']??'')?></td></tr><?php endforeach; ?></table><h2>4. Eventos especiales / altas de médicos</h2><p>________________________________________________________________________________</p><h2>5. Comentarios del mercado y competencia</h2><p>________________________________________________________________________________</p><br><p>Firma del Visitador Médico: ____________________________________</p></body></html>